    /// Task counts keyed by status, including closed tasks.
    public var counts: [String: JSONValue]
    public var epic: String
    /// Epic entity ID; null for legacy label groups.
    public var id: String??
    public var nextReady: [TaskEpicReady]
    /// Owner of the epic's primary task, as `id`, `name`, `alias` and `profile_picture`. The primary task is the top-ranked root blocker (the open task that unblocks the most work), or when no task blocks another, the highest-priority open task (lowest priority number, then ID). `null` when that task is unassigned or the epic has no open task.
    public var owner: Actor??
    /// The primary task whose owner is reported in `owner`. `null` when the epic has no open task.
    public var primaryTask: TaskEpicReady??
    public var rootBlockers: [TaskEpicBlocker]
    /// True when root ranking used a truncated in-epic graph.
    public var rootBlockersPartial: Bool
    public var topOpenPriority: Int??
    public var updatedAt: Date

    public init(
        blockedCount: Int,
        counts: [String: JSONValue],
        epic: String,
        id: String?? = nil,
        nextReady: [TaskEpicReady],
        owner: Actor?? = nil,
        primaryTask: TaskEpicReady?? = nil,
        rootBlockers: [TaskEpicBlocker],
        rootBlockersPartial: Bool,
        topOpenPriority: Int?? = nil,
        updatedAt: Date
    ) {
        self.blockedCount = blockedCount
        self.counts = counts
        self.epic = epic
        self.id = id
        self.nextReady = nextReady
        self.owner = owner
        self.primaryTask = primaryTask
        self.rootBlockers = rootBlockers
        self.rootBlockersPartial = rootBlockersPartial
        self.topOpenPriority = topOpenPriority
        self.updatedAt = updatedAt
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.blockedCount = try container.decode(Int.self, forKey: .blockedCount)
        self.counts = try container.decode([String: JSONValue].self, forKey: .counts)
        self.epic = try container.decode(String.self, forKey: .epic)
        self.id = try container.contains(.id) ? .some(container.decodeIfPresent(String.self, forKey: .id)) : nil
        self.nextReady = try container.decode([TaskEpicReady].self, forKey: .nextReady)
        self.owner = try container.contains(.owner) ? .some(container.decodeIfPresent(Actor.self, forKey: .owner)) : nil
        self.primaryTask = try container.contains(.primaryTask) ? .some(container.decodeIfPresent(TaskEpicReady.self, forKey: .primaryTask)) : nil
        self.rootBlockers = try container.decode([TaskEpicBlocker].self, forKey: .rootBlockers)
        self.rootBlockersPartial = try container.decode(Bool.self, forKey: .rootBlockersPartial)
        self.topOpenPriority = try container.contains(.topOpenPriority) ? .some(container.decodeIfPresent(Int.self, forKey: .topOpenPriority)) : nil
        self.updatedAt = try container.decode(Date.self, forKey: .updatedAt)
    }

    private enum CodingKeys: String, CodingKey {
        case blockedCount = "blocked_count"
        case counts
        case epic
        case id
        case nextReady = "next_ready"
        case owner
        case primaryTask = "primary_task"
        case rootBlockers = "root_blockers"
        case rootBlockersPartial = "root_blockers_partial"
        case topOpenPriority = "top_open_priority"
        case updatedAt = "updated_at"
    }
}

/// Label-summary representation of an owner's Epic collection.
public struct TaskEpicSummaryPage: Codable, Sendable {
    public var afterCursor: String??
    public var beforeCursor: String??
    public var data: [TaskEpicSummary]
    public var hasMore: Bool
    public var noEpicOpenCount: Int

    public init(
        afterCursor: String?? = nil,
        beforeCursor: String?? = nil,
        data: [TaskEpicSummary],
        hasMore: Bool,
        noEpicOpenCount: Int
    ) {
        self.afterCursor = afterCursor
        self.beforeCursor = beforeCursor
        self.data = data
        self.hasMore = hasMore
        self.noEpicOpenCount = noEpicOpenCount
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.afterCursor = try container.contains(.afterCursor) ? .some(container.decodeIfPresent(String.self, forKey: .afterCursor)) : nil
        self.beforeCursor = try container.contains(.beforeCursor) ? .some(container.decodeIfPresent(String.self, forKey: .beforeCursor)) : nil
        self.data = try container.decode([TaskEpicSummary].self, forKey: .data)
        self.hasMore = try container.decode(Bool.self, forKey: .hasMore)
        self.noEpicOpenCount = try container.decode(Int.self, forKey: .noEpicOpenCount)
    }

    private enum CodingKeys: String, CodingKey {
        case afterCursor = "after_cursor"
        case beforeCursor = "before_cursor"
        case data
        case hasMore = "has_more"
        case noEpicOpenCount = "no_epic_open_count"
    }
}

/// An indexed external object linked to a task.
public struct TaskExternalLink: Codable, Sendable {
    /// External container identity.
    public var externalScope: String
    /// Object identity within that container.
    public var objectId: String
    /// External object kind.
    public var objectType: String

    public init(externalScope: String, objectId: String, objectType: String) {
        self.externalScope = externalScope
        self.objectId = objectId
        self.objectType = objectType
    }

    private enum CodingKeys: String, CodingKey {
        case externalScope = "external_scope"
        case objectId = "object_id"
        case objectType = "object_type"
    }
}

/// The background job accepted for a task ownership conversion.
/// Acceptance authorizes the root only. The worker validates and checkpoints the
/// connected graph before transferring ownership; validation can fail after 202.
public struct TaskOwnershipJob: Codable, Sendable {
    /// Background job ID.
    public var jobId: Int
    /// Completed transfers are still reaching task read models. False when preparation failed or the job was cancelled before selecting tasks.
    public var projectionPending: Bool?
    /// Current background job state.
    public var status: String

    public init(jobId: Int, projectionPending: Bool? = nil, status: String) {
        self.jobId = jobId
        self.projectionPending = projectionPending
        self.status = status
    }

    private enum CodingKeys: String, CodingKey {
        case jobId = "job_id"
        case projectionPending = "projection_pending"
        case status
    }
}

/// A task-session lease returned only to its matching holder.
public struct TaskSessionLease: Codable, Sendable {
    /// Server-calculated lease expiry in ISO 8601 format.
    public var expiresAt: Date
    /// Bounded harness identifier for the matching coding session.
    public var harness: String
    /// Caller-generated fencing token required for renewal and release.
    public var leaseId: String
    /// Milliseconds of lease left when the response was built, clamped at zero. A renewal made while more than half the lease remains appends no event and leaves the expiry unchanged, so clients derive their deadline from this value.
    public var leaseRemainingMs: Int
    /// Server timestamp for the most recent claim, reclaim, or renewal.
    public var renewedAt: Date
    /// Opaque caller-generated coding-session identifier.
    public var sessionId: String
    /// Display name supplied by the matching coding session.
    public var sessionName: String
    /// Task aggregate version including the claim, reclaim, or renewal event.
    public var taskAggregateVersion: Int
    /// Native task status after the lease event.
    public var taskStatus: String

    public init(
        expiresAt: Date,
        harness: String,
        leaseId: String,
        leaseRemainingMs: Int,
        renewedAt: Date,
        sessionId: String,
        sessionName: String,
        taskAggregateVersion: Int,
        taskStatus: String
    ) {
        self.expiresAt = expiresAt
        self.harness = harness
        self.leaseId = leaseId
        self.leaseRemainingMs = leaseRemainingMs
        self.renewedAt = renewedAt
        self.sessionId = sessionId
        self.sessionName = sessionName
        self.taskAggregateVersion = taskAggregateVersion
        self.taskStatus = taskStatus
    }

    private enum CodingKeys: String, CodingKey {
        case expiresAt = "expires_at"
        case harness
        case leaseId = "lease_id"
        case leaseRemainingMs = "lease_remaining_ms"
        case renewedAt = "renewed_at"
        case sessionId = "session_id"
        case sessionName = "session_name"
        case taskAggregateVersion = "task_aggregate_version"
        case taskStatus = "task_status"
    }
}
